      text: "During developing water stress, an ABA-responsive leaf accumulates ABA. Which immediate response helps conserve water?",
      options: [{ key: "a", text: "Stomatal aperture decreases." }, { key: "b", text: "Stomatal aperture increases." }, { key: "c", text: "Aleurone starch synthesis stops." }, { key: "d", text: "Lateral buds elongate rapidly." }],
      answer: "a",
